-- 02-master.sql
--
-- EXTRACTED VERBATIM from artifacts/v1/gaos-arcadedb-model.html, which is the
-- source of truth for this schema. Do not edit this file to change the model:
-- change the document, then re-extract. A deviation that lives only here is a
-- schema nobody reviewing the model document would ever see.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

CREATE VERTEX TYPE Tenant IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Tenant.name               STRING  (mandatory true, notnull true);
CREATE PROPERTY Tenant.plan               STRING  (default 'standard');
CREATE PROPERTY Tenant.maxConcurrentTasks INTEGER (default 8, min 1);
CREATE PROPERTY Tenant.budgetCapUsd       FLOAT   (default 500.0, min 0);

-- readinessScore / readinessBand are the gate from architecture §07.
-- Stored, not computed on read: the scheduler checks them on every plan
-- request and a recompute-per-read would dominate the request.
CREATE VERTEX TYPE Product IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Product.name           STRING  (mandatory true, notnull true, min 2);
CREATE PROPERTY Product.code           STRING  (notnull true);
CREATE PROPERTY Product.owner          STRING;
CREATE PROPERTY Product.stage          STRING  (default 'draft', regexp 'draft|live|archived');
CREATE PROPERTY Product.readinessScore INTEGER (default 0, min 0, max 100);
CREATE PROPERTY Product.readinessBand  STRING  (default 'INSUFFICIENT',
                 regexp 'INSUFFICIENT|MINIMUM|WORKING|COMPLETE');
CREATE PROPERTY Product.driftPenalty   INTEGER (default 0, min 0, max 25);
CREATE PROPERTY Product.lastInjectedAt DATETIME;
CREATE PROPERTY Product.lastReviewedAt DATETIME;

CREATE VERTEX TYPE Requirement IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Requirement.kind      STRING (mandatory true, notnull true,
                 regexp 'goal|rule|scope|out_of_scope|constraint');
CREATE PROPERTY Requirement.text      STRING (mandatory true, notnull true, min 8);
CREATE PROPERTY Requirement.sourceRef STRING;
CREATE PROPERTY Requirement.active    BOOLEAN (default true);

CREATE VERTEX TYPE Issue IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Issue.key      STRING (mandatory true, notnull true);   -- US-01
CREATE PROPERTY Issue.role     STRING (mandatory true, notnull true);
CREATE PROPERTY Issue.want     STRING (mandatory true, notnull true);
CREATE PROPERTY Issue.benefit  STRING;
CREATE PROPERTY Issue.priority STRING (default 'should', regexp 'must|should|could');
CREATE PROPERTY Issue.status   STRING (default 'OPEN', regexp 'OPEN|PLANNED|DELIVERED|DROPPED');

CREATE VERTEX TYPE AcceptanceCriterion IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY AcceptanceCriterion.text       STRING (mandatory true, notnull true, min 5);
CREATE PROPERTY AcceptanceCriterion.verifiedBy STRING;   -- test id, replay, manual
CREATE PROPERTY AcceptanceCriterion.verifiedAt DATETIME;

-- Artifact is hybrid: kind and title are declared, body shape is not.
-- body holds small sources (a sequence diagram); bodyRef points at object
-- storage for anything large. Never both.
CREATE VERTEX TYPE Artifact IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Artifact.kind      STRING (mandatory true, notnull true,
                 regexp 'sequence|erd|flow|diff|commit|report|log|upload');
CREATE PROPERTY Artifact.title     STRING (notnull true);
CREATE PROPERTY Artifact.body      STRING;
CREATE PROPERTY Artifact.bodyRef   STRING;
CREATE PROPERTY Artifact.mimeType  STRING;
CREATE PROPERTY Artifact.sizeBytes LONG (min 0);

CREATE VERTEX TYPE Metric IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Metric.name       STRING (mandatory true, notnull true);
CREATE PROPERTY Metric.target     STRING;
CREATE PROPERTY Metric.unit       STRING;
CREATE PROPERTY Metric.current    FLOAT;
CREATE PROPERTY Metric.measuredAt DATETIME;
